class Solution {
  private int[][][][] memo = new int[29][29][29][];

  public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
    return solve(n, Math.min(firstPlayer, secondPlayer), Math.max(firstPlayer, secondPlayer));
  }

  // {earliest, latest} round in which the players at positions f < s (1-indexed) meet among n
  // players
  private int[] solve(int n, int f, int s) {
    if (f + s == n + 1) return new int[] {1, 1};
    if (memo[n][f][s] != null) return memo[n][f][s];
    int half = (n + 1) / 2, earliest = Integer.MAX_VALUE, latest = 0;
    // pair i plays n + 1 - i; f and s always win, every other pair can go either way
    for (int mask = 0; mask < (1 << (n / 2)); mask++) {
      int[] winners = new int[half];
      boolean canonical = true;
      for (int i = 1; i <= half; i++) {
        int j = n + 1 - i;
        boolean fixed = i == j || i == f || j == f || i == s || j == s;
        boolean bit = ((mask >> (i - 1)) & 1) == 1;
        if (fixed && bit && i != j) canonical = false; // each forced pair is enumerated once
        int w = i == j ? i : (i == f || j == f) ? f : (i == s || j == s) ? s : bit ? j : i;
        winners[i - 1] = w;
      }
      if (!canonical) continue;
      Arrays.sort(winners);
      int newF = Arrays.binarySearch(winners, f) + 1, newS = Arrays.binarySearch(winners, s) + 1;
      int[] next = solve(half, newF, newS);
      earliest = Math.min(earliest, next[0] + 1);
      latest = Math.max(latest, next[1] + 1);
    }
    return memo[n][f][s] = new int[] {earliest, latest};
  }
}
